// Karplus-Strong on a 4096-sample delay buffer.
// in1 = freq (Hz), in2 = decay (0..1), in3 = retrigger period (samples).
const DELAY_LEN = 4096;
const buf = buffer.f32({ size: DELAY_LEN, name: 'ks_buf' });
const head = state.i32(0, { name: 'ks_head' });
const seed = state.i32(0xCAFEF00D | 0, { name: 'ks_seed' });
const pluckCount = state.i32(0, { name: 'ks_pluck' });
const tickAcc = state.i32(0, { name: 'ks_tick' });

// Auto-retrigger every (sr / 2) samples so the demo plays continuously.
// Period of one full pluck-and-decay cycle ≈ 0.5 s.
const RETRIG = 24000;
const tNext = tickAcc.load().add(1);
const tFire = tNext.gte(i32(RETRIG));
tickAcc.store(select(tFire, i32(0), tNext));

// Period in samples, computed from in1 (Hz).
const period = num(48000).div(in1.max(20)).toI32();
// On retrigger: refill `period` samples with noise.
const pcDec = pluckCount.load().sub(1);
const pcClamped = select(pcDec.gte(0), pcDec, i32(0));
pluckCount.store(select(tFire, period, pcClamped));

// PRNG.
const r = seed.load().mul(1103515245).add(12345);
seed.store(r);
const noise = r.toF32().mul(1 / 2147483648);

const h = head.load();
const wIdx = h.mod(DELAY_LEN);
const rIdx = h.sub(period).add(DELAY_LEN).mod(DELAY_LEN);

// Cheap LP (avg of two neighbours), apply decay.
const tap = buf.read(rIdx);
const tapPrev = buf.read(rIdx.sub(1).add(DELAY_LEN).mod(DELAY_LEN));
const lp = tap.add(tapPrev).mul(0.5);
const fed = flushDenormals(lp.mul(in2));

// Noise during the pluck window; otherwise feedback through the filter.
const sample = select(pluckCount.load().gt(0), noise, fed);
buf.write(wIdx, sample);
head.store(h.add(1));

return [sample];
